using UnityEditor;
using UnityEngine;

public static class NormalizePolygonFarmLitMaterials
{
    public static string Main()
    {
        var guids = AssetDatabase.FindAssets("t:Material", new[] { "Assets/PolygonFarm/Materials" });
        int normalized = 0;
        foreach (var guid in guids)
        {
            var material = AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(guid));
            if (material == null || material.shader == null || material.shader.name != "Universal Render Pipeline/Lit")
                continue;

            material.SetColor("_BaseColor", Color.white);
            material.SetFloat("_Metallic", 0f);
            material.SetFloat("_Smoothness", 0.2f);
            EditorUtility.SetDirty(material);
            normalized++;
        }
        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        return $"Cor-base e acabamento normalizados em {normalized} materiais URP/Lit.";
    }
}
